def seed_current_academic_year(apps, schema_editor):
    AcademicYear = apps.get_model('core', 'AcademicYear')
    PopulationDataSubmission = apps.get_model('core', 'PopulationDataSubmission')
    BarangayPopulationMetrics = apps.get_model('core', 'BarangayPopulationMetrics')
    EnrollmentData = apps.get_model('core', 'EnrollmentData')
    ChildrenGapAnalysis = apps.get_model('core', 'ChildrenGapAnalysis')
    SNPPlanningRecommendation = apps.get_model('core', 'SNPPlanningRecommendation')
    DataIntegrationLog = apps.get_model('core', 'DataIntegrationLog')
    Child = apps.get_model('core', 'Child')

    academic_year, _ = AcademicYear.objects.get_or_create(
        name='2026-2027',
        defaults={
            'start_year': 2026,
            'end_year': 2027,
            'start_date': '2026-06-01',
            'end_date': '2027-05-31',
            'is_active': True,
        },
    )

    for model in [
        PopulationDataSubmission,
        BarangayPopulationMetrics,
        EnrollmentData,
        ChildrenGapAnalysis,
        SNPPlanningRecommendation,
        DataIntegrationLog,
        Child,
    ]:
        model.objects.filter(academic_year__isnull=True).update(academic_year=academic_year)

    for child in Child.objects.filter(student_id__isnull=True):
        if child.cdc_id and not child.barangay_id:
            child.barangay_id = child.cdc.barangay_id
        child.student_id = f'CSWDO-{academic_year.start_year}-{child.pk:06d}'
        child.save(update_fields=['student_id', 'barangay'])


